      "path": "package.json",
      "content": "{\n  \"name\": \"dsh-armory\",\n  \"version\": \"2.1.0\",\n  \"description\": \"Unified Skill + MCP + Expert + Plugin board for DeepSeek Harness (desktop app and Web GUI) — global panel page, JSON import, WorkBuddy connector & SkillHub & Expert & CodeBuddy plugin & awesome-dsh-plugins market installs, MCP OAuth authorization, tool-usage tailor, and profile-backed Host Remote management.\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/2026heshao/dsh-armory.git\"\n  },\n  \"homepage\": \"https://github.com/2026heshao/dsh-armory#readme\",\n  \"bugs\": {\n    \"url\": \"https://github.com/2026heshao/dsh-armory/issues\"\n  },\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"engines\": {\n    \"node\": \">=22.15\"\n  },\n  \"scripts\": {\n    \"test\": \"node ./test/run-all.mjs\",\n    \"test:expert\": \"node ./test/run-expert-manual.mjs\",\n    \"test:upgrade\": \"node ./test/upgrade-plan.mjs\",\n    \"test:install\": \"node ./test/verify-install-info.mjs\",\n    \"test:host\": \"node ./test/verify-host-installinfo.mjs\",\n    \"test:e2e\": \"node ./test/run-e2e.mjs\",\n    \"lint\": \"eslint .\",\n    \"format\": \"prettier --write \\\"lib/**/*.js\\\" \\\"test/**/*.mjs\\\" \\\"*.mjs\\\" \\\"*.json\\\"\",\n    \"format:check\": \"prettier --check \\\"lib/**/*.js\\\" \\\"test/**/*.mjs\\\" \\\"*.mjs\\\" \\\"*.json\\\"\",\n    \"migrate\": \"node ./test/run.mjs migrate\"\n  },\n  \"exports\": {\n    \"./typert\": \"./lib/typert.js\",\n    \"./client\": \"./lib/client.js\",\n    \".\": \"./lib/index.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib\",\n    \"docs/*.md\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"LICENSE\"\n  ],\n  \"dependencies\": {\n    \"smol-toml\": \"^1.8.0\",\n    \"yaml\": \"2.9.0\",\n    \"zod\": \"4.4.3\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.2\",\n    \"@deepseek-ai/cordis-plugin-lo