ull);\n    }\n  }, [call]);\n  // T06/Awesome：DSH 社区插件市场（awesome-dsh-plugins）状态机与数据接入。\n  // pluginSource 持久化 localStorage（先例 UPDATE_HINT_STATE_KEY）；默认 awesome（用户拍板 2026-10-20：插件页初始显示 DSH 社区；显式切过来源的用户按其持久化值）。\n  // 来源切换控件在插件工具行（select 两态），写入 localStorage 持久化。\n  // 注意：必须在下方两个依赖数组含 pluginSource 的 effect 之前声明——依赖数组在渲染期求值，\n  // const 声明若在其后，渲染即抛 ReferenceError: Cannot access 'pluginSource' before initialization（TDZ）。\n  const [pluginSource, setPluginSource] = useState(() => {\n    try { return localStorage.getItem('dsh-armory.pluginSource') === 'codebuddy' ? 'codebuddy' : 'awesome'; } catch { return 'awesome'; }\n  });\n  const pluginUpdateChecked = useRef(false);\n  useEffect(() => {\n    if (tab === 'plugin' && pluginSource === 'codebuddy' && !plugins.length && !pluginsLoading) loadPlugins();\n  }, [tab, pluginSource, plugins.length, pluginsLoading, loadPlugins]);\n  useEffect(() => {\n    // 只在目录加载完成后探一次；pluginUpdateChecked 保证组件存续期内不重复。\n    if (tab !== 'plugin' || pluginSource !== 'codebuddy' || pluginsLoading || !plugins.length || pluginUpdateChecked.current) return;\n    pluginUpdateChecked.current = true;\n    checkPluginUpdate();\n  }, [tab, pluginSource, pluginsLoading, plugins.length, checkPluginUpdate]);\n  // 首屏秒开：首次挂载就把上次的快照铺上，用户进插件页立刻看到目录而不是一句「正在加载」。\n  // 快照只在挂载时读一次（JSON.parse 一两 MB 不能每次 render 都干）；真实目录随后覆盖。\n  const awesomeSnapshotRef = useRef(undefined);\n  if (awesomeSnapshotRef.current === undefined) awesomeSnapshotRef.current = readAwesomeSnapshot();\n  const [awesomePlugins, setAwesomePlugins] = useState(() => {\n    const snapshot = awesomeSnapshotRef.current;\n    return snapshot ? snapshot.plugins.map((item) => ({ ...item, marketplace: snapshot.marketplace || 'awesome-dsh-plugins' })) : [];\n  });\n  const [awesomeLoading, setAwesomeLoading] = useState(false);\n  const [awesomeError, setAwesomeError] = useState('');\n  const [awesomeUpdateHint, setAwesomeUpdateHint] = useState(null);\n  const [awesomeStale, setAwesomeStale] = useState(false);\n